package example.inventory.domain;

public record Item(String sku, String name, int quantity, long priceCents) {
    public Item {
        if (sku == null || sku.isBlank()) throw new IllegalArgumentException("sku is required");
        if (name == null || name.isBlank()) throw new IllegalArgumentException("name is required");
        if (quantity < 0) throw new IllegalArgumentException("quantity must be >= 0");
        if (priceCents < 0) throw new IllegalArgumentException("price must be >= 0");
    }
    public Item withQuantity(int newQuantity) {
        return new Item(sku, name, newQuantity, priceCents);
    }
}

