package example.inventory.persistence;

import example.inventory.domain.Item;
import java.io.IOException;
import java.util.List;
import java.util.Optional;

public interface InventoryRepository {
    List<Item> findAll() throws IOException;
    Optional<Item> findBySku(String sku) throws IOException;
    void save(Item item) throws IOException;
    void delete(String sku) throws IOException;
    void flush() throws IOException;
}

package example.inventory.persistence;

import example.inventory.domain.Item;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public final class FileInventoryRepository implements InventoryRepository {
    private static final String HEADER = "sku\tname\tquantity\tpriceCents";
    private final Path file;
    private final Map<String, Item> items = new LinkedHashMap<>();

    public FileInventoryRepository(Path file) throws IOException {
        this.file = file;
        load();
    }

    public synchronized List<Item> findAll() { return List.copyOf(items.values()); }
    public synchronized Optional<Item> findBySku(String sku) { return Optional.ofNullable(items.get(sku)); }
    public synchronized void save(Item item) { items.put(item.sku(), item); }
    public synchronized void delete(String sku) { items.remove(sku); }

    public synchronized void flush() throws IOException {
        Path parent = file.toAbsolutePath().getParent();
        if (parent != null) Files.createDirectories(parent);
        Path temp = file.resolveSibling(file.getFileName() + ".tmp");
        List<String> lines = new ArrayList<>();
        lines.add(HEADER);
        for (Item item : items.values()) {
            String safeName = item.name().replace("\t", " ");
            lines.add(item.sku()+"\t"+safeName+"\t"+item.quantity()+"\t"+item.priceCents());
        }
        Files.write(temp, lines, StandardCharsets.UTF_8,
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
        Files.move(temp, file, StandardCopyOption.REPLACE_EXISTING);
    }

    private void load() throws IOException {
        if (!Files.exists(file)) return;
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        for (int i=1; i<lines.size(); i++) {
            String[] parts = lines.get(i).split("\\t", -1);
            if (parts.length != 4) throw new IOException("Malformed inventory row at line "+(i+1));
            Item item = new Item(parts[0], parts[1], Integer.parseInt(parts[2]), Long.parseLong(parts[3]));
            items.put(item.sku(), item);
        }
    }
}

