package example.inventory.application;

import example.inventory.domain.*;
import example.inventory.persistence.InventoryRepository;
import java.io.IOException;
import java.util.List;

public final class InventoryService {
    private final InventoryRepository repository;
    public InventoryService(InventoryRepository repository) { this.repository = repository; }

    public synchronized void add(Item item) throws IOException {
        if (repository.findBySku(item.sku()).isPresent())
            throw new InventoryException("SKU already exists: " + item.sku());
        repository.save(item); repository.flush();
    }
    public List<Item> list() throws IOException { return repository.findAll(); }
    public Item find(String sku) throws IOException {
        return repository.findBySku(sku)
                .orElseThrow(() -> new InventoryException("SKU not found: " + sku));
    }
    public synchronized void restock(String sku, int amount) throws IOException {
        if (amount <= 0) throw new InventoryException("restock amount must be positive");
        Item current=find(sku);
        repository.save(current.withQuantity(current.quantity()+amount)); repository.flush();
    }
    public synchronized void sell(String sku, int amount) throws IOException {
        if (amount <= 0) throw new InventoryException("sale amount must be positive");
        Item current=find(sku);
        if (current.quantity() < amount) throw new InventoryException("insufficient stock for " + sku);
        repository.save(current.withQuantity(current.quantity()-amount)); repository.flush();
    }
    public synchronized void remove(String sku) throws IOException {
        find(sku); repository.delete(sku); repository.flush();
    }
}

