package example.inventory.cli;

import example.inventory.application.InventoryService;
import example.inventory.domain.*;
import example.inventory.persistence.*;
import java.io.*;
import java.nio.file.Path;
import java.util.concurrent.*;

public final class Main {
    public static void main(String[] args) throws Exception {
        Path data = Path.of(System.getenv().getOrDefault("INVENTORY_FILE", "data/inventory.tsv"));
        FileInventoryRepository repository = new FileInventoryRepository(data);
        InventoryService service = new InventoryService(repository);

        System.out.println("Java Inventory Service. Commands: add, list, find, restock, sell, remove, exit");
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            String line;
            while ((line = reader.readLine()) != null) {
                line=line.trim();
                if (line.equals("exit")) break;
                if (line.isBlank()) continue;
                try { dispatch(service, line); }
                catch (InventoryException | IllegalArgumentException e) {
                    System.err.println("Input/domain error: " + e.getMessage());
                } catch (IOException e) {
                    System.err.println("I/O error: " + e.getMessage());
                }
            }
            Future<?> flush=executor.submit(repository::flush);
            try { flush.get(2, TimeUnit.SECONDS); }
            catch (TimeoutException e) {
                flush.cancel(true);
                System.err.println("Final persistence flush timed out.");
            }
        }
    }

    private static void dispatch(InventoryService service, String line) throws IOException {
        String[] p=line.split("\\s+", 5);
        switch (p[0]) {
            case "list" -> service.list().forEach(System.out::println);
            case "find" -> System.out.println(service.find(require(p,1)));
            case "add" -> service.add(new Item(require(p,1), require(p,2),
                    Integer.parseInt(require(p,3)), Long.parseLong(require(p,4))));
            case "restock" -> service.restock(require(p,1), Integer.parseInt(require(p,2)));
            case "sell" -> service.sell(require(p,1), Integer.parseInt(require(p,2)));
            case "remove" -> service.remove(require(p,1));
            default -> System.err.println("Unknown command: " + p[0]);
        }
    }

    private static String require(String[] parts, int index) {
        if (parts.length <= index || parts[index].isBlank())
            throw new IllegalArgumentException("missing argument " + index);
        return parts[index];
    }
}

