    private final InventoryService service=new InventoryService(repo);

    @Test void sellDecreasesQuantity() throws IOException {
        service.add(new Item("SKU-1","Keyboard",10,2500));
        service.sell("SKU-1",3);
        assertEquals(7,service.find("SKU-1").quantity());
    }

